    private fun bools(xs: IntArray) = BooleanArray(xs.size) { xs[it] != 0 }

    /** Same as the Python fixture: sum of channel value * ((flat index % 997) + 1), order R, G, B per pixel. */
    private fun checksum(px: IntArray): Long {
        var s = 0L
        var i = 0
        for (p in px) for (shift in intArrayOf(16, 8, 0)) {
            s += ((p shr shift) and 0xFF).toLong() * ((i % 997) + 1)
            i++
        }
        return s
    }

    @Test
    fun resizeEnlargingMatchesPillow() {
        assertArrayEquals(UP_OUT, PilResize.resize(UP_IN, 5, 4, 9, 7))
    }

    @Test
    fun resizeMixedDirectionsMatchesPillow() {
        assertArrayEquals(MIX_OUT, PilResize.resize(MIX_IN, 11, 3, 4, 8))
    }

    @Test
    fun cropWindowMatchesPython() {
        assertEquals(MaskCrop.Window(7, 1, 6), MaskCrop.window(bools(WIN_MASK), 13, 9))
    }

    @Test
    fun emptyMaskHasNoWindow() {
        assertEquals(null, MaskCrop.window(BooleanArray(12), 4, 3))
    }

    @Test
    fun fillCropResizeMatchesCropToMask() {
        val mask = bools(CHAIN_MASK)
        val win = MaskCrop.window(mask, 40, 30)!!
        assertEquals(MaskCrop.Window(18, 1, 22), win)
        val square = MaskCrop.fillAndCrop(CHAIN_PHOTO, mask, 40, 30, win)
        val out = PilResize.resize(square, win.side, win.side, 224, 224)
        assertEquals(9334339177L, checksum(out))
    }

    @Test
    fun statsMatchNumpy() {
        val s = Summary.of(STATS_IN)
        val ref = doubleArrayOf(7.416081081081081, 3.439695734108359, 1.21, 5.126, 7.375, 8.886, 10.137599999999999, 17.53)
        val got = doubleArrayOf(s.mean, s.sd, s.min, s.q1, s.median, s.q3, s.p90, s.max)
        for (k in ref.indices) assertEquals(ref[k], got[k], 1e-9)
    }
